trait Dispenser {
    type Item;
    fn dispense(&mut self) -> Option<Self::Item>;
}

struct TicketRoll {
    next: u32,
    last: u32,
}

impl Dispenser for TicketRoll {
    type Item = u32;

    fn dispense(&mut self) -> Option<u32> {
        if self.next > self.last {
            return None;
        }
        self.next += 1;
        Some(self.next - 1)
    }
}

fn main() {
    let mut roll = TicketRoll { next: 1, last: 3 };
    println!("{:?}", roll.dispense());
    println!("{:?}", roll.dispense());
    println!("{:?}", roll.dispense());
    println!("{:?}", roll.dispense());
}

