use std::fmt::Debug;

trait Speak {
    fn speak(&self) -> String;
}

#[derive(Debug, PartialEq, PartialOrd)]
struct Book {
    pages: u32,
}

#[derive(Debug)]
struct Parrot {
    name: String,
}

impl Speak for Parrot {
    fn speak(&self) -> String {
        format!("{}: Squawk!", self.name)
    }
}

impl Speak for i32 {
    fn speak(&self) -> String {
        format!("{}!", self)
    }
}

fn can_speak<T: Speak>(x: &T) -> String {
    x.speak()
}

fn can_debug<T: Debug>(x: &T) -> String {
    format!("{:?}", x)
}

fn can_compare<T: PartialOrd>(a: &T, b: &T) -> bool {
    a < b
}

fn main() {
    let small = Book { pages: 95 };
    let big = Book { pages: 340 };
    let polly = Parrot { name: String::from("Polly") };
    println!("Book   Debug:      {}", can_debug(&small));
    println!("Book   PartialOrd: {}", can_compare(&small, &big));
    println!("Parrot Speak:      {}", can_speak(&polly));
    println!("Parrot Debug:      {}", can_debug(&polly));
    println!("i32    Speak:      {}", can_speak(&7));
    println!("i32    Debug:      {}", can_debug(&7));
    println!("i32    PartialOrd: {}", can_compare(&7, &3));
}

